export function renderDriverSupport(api){
 const {shell,title,panel,field,select,icon,box,link,action,e,profile,stored,set,$,toast,modal}=api;
 const faq=[['How do I start accepting jobs?','Complete your profile and required verification in the production app. In this demo, open Projects, choose a Pending job and select Accept Job.'],['Why is my payment pending?','A completed delivery must be reviewed and paid by the payment system. Earnings shown here are samples; payouts are not connected.'],['How do I update my vehicle details?','Go to your profile and open Vehicle Subscription. Change your primary vehicle and job preferences, then save.'],['How do background checks work?','Background checks will be handled by a verified provider in the production app. Document selection here is a local demonstration.'],["I’m not receiving notifications — what do I do?",'Review your notification settings and verify your contact details. This prototype does not send push, email, or SMS notifications.'],['What should I do if I have an accident during a delivery?','Ensure everyone is safe and contact local emergency services when needed. Contact your delivery support team for help with the job.'],['How do I cancel or reschedule an accepted job?','Contact support from the job details page. Pending jobs can be declined without cancelling the customer booking.'],['What are the vehicle insurance requirements?','Check the current requirements with the service operator before accepting real jobs. The requirements in the design are illustrative and have not been verified.']];
 const draft=stored('365-driver-ticket-draft',{});
 shell(`<div class="d-support-title">${title('Support & Help Center','Get quick answers and contact our support team when needed.')}</div><section class="d-support-grid d-section">${[['0ab3e.svg','Contact Support','Reach out to our team for assistance.','Chat with Support','chat','#0d9488'],['c0794.svg','Submit a Ticket','Report an issue or request help.','Submit a Request','ticket','#f97316'],['fa89b.svg','Call Support','Speak directly with our support team.','Call Now','support-call','#16a34a']].map(x=>`<article class="d-card">${box(x[0])}<h3>${x[1]}</h3><p class="muted">${x[2]}</p><button type="button" class="btn" data-d-action="${x[4]}" style="background:${x[5]}">${x[3]}</button></article>`).join('')}</section><section class="d-section"><h2>Browse by Category</h2><div class="d-category-grid">${[['Getting Started','35799.svg'],['Payments & Earnings','470c4.svg'],['Vehicle Requirements','f291f.svg'],['Account & Verification','c6bd6.svg'],['Job Requests','6bbfb.svg'],['App Issues','8302e.svg']].map(x=>`<button type="button" class="d-category" data-d-category="${x[0]}">${box(x[1])}<h3>${x[0]}</h3><p>Find answers to common questions.</p></button>`).join('')}</div></section><section class="d-section" id="d-faq-section"><h2>Frequently Asked Questions</h2><div class="d-faq">${faq.map((x,i)=>`<details ${i===0?'open':''}><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div></section><div class="d-support-bottom" style="margin-top:64px"><form class="d-card d-support-form" id="d-ticket-form"><div><h2>Submit a Support Ticket</h2><p class="muted">Can't find what you're looking for? Send us a detailed message and we'll get back to you.</p></div>${field('Full Name','name',draft.name||profile.firstName+' '+profile.lastName,'text','required')}${field('Email Address','email',draft.email||profile.email,'email','required')}${select('Issue Category','category',['Select a category','Getting Started','Payments & Earnings','Vehicle Requirements','Account & Verification','Job Requests','App Issues'],draft.category||'Select a category','required')}<div class="field"><label for="d-description">Description of Issue</label><textarea id="d-description" name="description" rows="6" maxlength="500" required>${e(draft.description||'')}</textarea><small id="d-description-count">${(draft.description||'').length}/500 characters</small></div><label class="d-upload">Upload Screenshot (Optional)<br>PNG, JPG or JPEG (max. 5MB)<input type="file" id="d-ticket-file" accept=".png,.jpg,.jpeg"></label><button class="btn" type="submit">Submit Ticket</button><p class="d-auth-note">Demo only: the ticket is saved locally and is not sent to a support team. Attachments are not uploaded.</p></form><aside class="d-card d-support-contact"><h2>Contact Information</h2><p class="muted">Reach out to us directly through any of these channels.</p><div><small>Email</small><strong>Support address pending</strong></div><div><small>Phone</small><strong>Support hotline pending</strong></div><div><small>Working Hours (design sample)</small><strong>Mon - Fri: 8:00 AM - 8:00 PM</strong><strong>Sat - Sun: 9:00 AM - 6:00 PM</strong></div><div><small>Avg Response Time</small><strong>Under 24 hours (sample)</strong></div><div class="d-note-panel yellow"><strong>Emergency?</strong><p>Contact local emergency services for urgent safety issues. This demo is not monitored.</p></div></aside></div>`,{active:'Support',support:true});
 $('#d-description').oninput=()=>{$('#d-description-count').textContent=$('#d-description').value.length+'/500 characters'};
 $('#d-ticket-file').onchange=event=>{const f=event.target.files[0];if(f&&(f.size>5*1024*1024||!(/\.(png|jpe?g)$/i).test(f.name))){toast('Select a PNG or JPG smaller than 5MB.');event.target.value=''}};
 $('#d-ticket-form').oninput=()=>{const fd=new FormData($('#d-ticket-form'));set('365-driver-ticket-draft',Object.fromEntries(fd))};
 $('#d-ticket-form').onsubmit=event=>{event.preventDefault();if($('#d-category').value==='Select a category'){toast('Select an issue category.');return}const fd=new FormData(event.currentTarget),tickets=stored('365-driver-tickets',[]),id='TKT-'+crypto.randomUUID().slice(0,8).toUpperCase();tickets.unshift({...Object.fromEntries(fd),id,createdAt:new Date().toISOString(),status:'Saved Demo Ticket'});set('365-driver-tickets',tickets);modal('Demo Ticket Saved',`Ticket ${id} is saved in this browser. No message has been sent.`)};
 for(const b of document.querySelectorAll('[data-d-category]'))b.onclick=()=>{document.querySelectorAll('[data-d-category]').forEach(x=>x.classList.toggle('active',x===b));$('#d-category').value=b.dataset.dCategory;$('#d-faq-section').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};
}
